// app/context/YearFilterContext.js
'use client'; // Obligatoire pour les hooks
import { createContext, useContext, useState, useEffect } from 'react';

const YearFilterContext = createContext();

export function YearFilterProvider({ children }) {
  // État initial synchronisé avec le serveur
  const [yearFilter, setYearFilter] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('yearFilter') || new Date().getFullYear().toString();
    }
    return new Date().getFullYear().toString();
  });

  // Persistance dans localStorage
  useEffect(() => {
    localStorage.setItem('yearFilter', yearFilter);
  }, [yearFilter]);

  return (
    <YearFilterContext.Provider value={{ yearFilter, setYearFilter }}>
      {children}
    </YearFilterContext.Provider>
  );
}

export const useYearFilter = () => {
  const context = useContext(YearFilterContext);
  if (!context) {
    throw new Error('useYearFilter must be used within YearFilterProvider');
  }
  return context;
};